def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    if not markers:
        return out

    # Compute shortest paths through the non-background drawing from each marker.
    distances = []
    for sr, sc, _ in markers:
        d = {(sr, sc): 0}
        q = deque([(sr, sc)])
        while q:
            r, c = q.popleft()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0 and (rr, cc) not in d:
                    d[(rr, cc)] = d[(r, c)] + 1
                    q.append((rr, cc))
        distances.append(d)

    # A closed 1-valued rectangle marks its interior. Accumulate all such
    # interiors, then color each marked cell by the closest marker along the shape.
    fill = set()
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[top][c] == 1 and grid[bottom][c] == 1 for c in range(left, right + 1)):
                        continue
                    if not all(grid[r][left] == 1 and grid[r][right] == 1 for r in range(top, bottom + 1)):
                        continue
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == 1:
                                fill.add((r, c))

    for r, c in fill:
        k = min(range(len(markers)), key=lambda i: distances[i].get((r, c), h * w + 1))
        out[r][c] = markers[k][2]
    return out
