def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    if not markers:
        return out

    # Find each marker's distance through the non-background drawing.
    distances = []
    for sr, sc, _ in markers:
        dist = {(sr, sc): 0}
        queue = deque([(sr, sc)])
        while queue:
            r, c = queue.popleft()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if (0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0
                        and (rr, cc) not in dist):
                    dist[(rr, cc)] = dist[(r, c)] + 1
                    queue.append((rr, cc))
        distances.append(dist)

    # Recolor only cells fully enclosed in the 8-neighborhood by the drawing.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            enclosed = all(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] != 0
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            )
            if enclosed:
                i = min(range(len(markers)), key=lambda j: distances[j].get((r, c), h * w + 1))
                out[r][c] = markers[i][2]
    return out
