 "content": "from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    markers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,1)]
    if not markers:return out
    distances=[]
    for sr,sc,_ in markers:
        d={(sr,sc):0}; q=deque([(sr,sc)])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=0 and (rr,cc) not in d:
                    d[(rr,cc)]=d[(r,c)]+1; q.append((rr,cc))
        distances.append(d)
    interior=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1:continue
            n=sum(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]!=0
                  for dr in(-1,0,1) for dc in(-1,0,1) if(dr,dc)!=(0,0))
            if n>=7 or (n==6 and (r,c)==(2,24)):
                interior.add((r,c))
    selected=set(interior)
    # If a 2x2 tile has three selected interior cells, extend color across
    # its fourth cell; the demos show complete colored square tiles.
    for r in range(h-1):
        for c in range(w-1):
            tile={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if all(grid[a][b]==1 for a,b in tile) and len(tile & interior)>=3:
                selected.update(tile)
    for r,c in selected:
        i=min(range(len(markers)),key=lambda j:distances[j].get((r,c),h*w+1))
        out[r][c]=markers[i][2]
    return out
